window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-006"]={"KLHL23":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["BioPlex","pubmed:21145461","pubmed:30190310","pubmed:33130828","pubmed:34591642","pubmed:34878901","pubmed:35563538","pubmed:37495603"],"pmids":["21145461","28514442","30190310","33130828","33961781","34591642","34878901","35563538","37495603"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens CAL-33 tongue squamous carcinoma cell\", \"human-cal33\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"USP22","hgnc":"HGNC:12621","core":true,"core_annotation":{"hgnc":"HGNC:12621","symbol_at_source":"USP22","accession":"Q9UPT9","function":"Histone modification write cofactor","target":"histone","pmids":["18469533"],"complexes":"SAGA","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":122,"hub_weight":0.5391638660171921,"quality":0.65,"programmes":["pubmed:19615732"],"pmids":["19615732"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinase that plays a role in several cellular processes including transcriptional regulation, cell cycle progression or innate immunity. As part of the transcription regulatory histone acetylation (HAT) complex SAGA, catalyzes the deubiquitination of both histones H2A and H2B, thereby acting as a transcriptional coactivator (PubMed:18206972, PubMed:18206973, PubMed:18469533). Recruited to specific gene promoters by activators such as MYC, where it is required for transcription. Facilitates cell-cycle progression by stabilizing CCNB1 and antagonizing its proteasome-mediated degradation in a cell cycle-specific manner (PubMed:27030811). Modulates cell cycle progression and apoptosis also by antagonizing TP53 transcriptional activation through deacetylase SIRT1 stabilization (PubMed:22542455). Plays multiple roles in immunity and inflammation. Participates in antiviral response by deubiquitinating the importin KPNA2, leading to IRF3 nuclear translocation and subsequent type I interferon production (PubMed:32130408). Acts as a central regulator of type III IFN signaling by negatively regulating STING1 activation and ubiquitination (PubMed:35933402). Inhibits NLRP3 inflammasome activation by promoting NLRP3 degradation through ATG5-dependent autophagy (By similarity). Deubiquitinates CD274 to induce its stabilization and thereby participates in maintenance of immune tolerance to self (PubMed:31399419). Controls necroptotic cell death by regulating RIPK3 phosphorylation and ubiquitination (PubMed:33369872). During bacterial infection, promotes pro-inflammatory response by targeting TRAF6 and removing its 'Lys-48'-linked polyubiquitination (By similarity)","source":"project UniProt records20261017/18"},{"partner":"WDR5","hgnc":"HGNC:12757","core":true,"core_annotation":{"hgnc":"HGNC:12757","symbol_at_source":"WDR5","accession":"P61964","function":"Histone modification read","target":"histone","pmids":["16946699"],"complexes":"ATAC, NSL, RING2-L3MBTL2, COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1007,"hub_weight":0.21749411414517786,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Contributes to histone modification (PubMed:16600877, PubMed:16829960, PubMed:19103755, PubMed:19131338, PubMed:19556245, PubMed:20018852). May position the N-terminus of histone H3 for efficient trimethylation at 'Lys-4' (PubMed:16829960). As part of the MLL1/MLL complex it is involved in methylation and dimethylation at 'Lys-4' of histone H3 (PubMed:19556245). H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:18840606). As part of the NSL complex it may be involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:19103755, PubMed:20018852). May regulate osteoblasts differentiation (By similarity). In association with RBBP5 and ASH2L, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SZRD1":{"coreEvidence":[{"partner":"GLYR1","hgnc":"HGNC:24434","core":true,"core_annotation":{"hgnc":"HGNC:24434","symbol_at_source":"GLYR1","accession":"Q49A26","function":"Histone modification read","target":"histone","pmids":["20850016"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":232,"hub_weight":0.42107596053325946,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Cytokine-like nuclear factor with chromatin gene reader activity involved in chromatin modification and regulation of gene expression (PubMed:23260659, PubMed:30970244). Acts as a nucleosome-destabilizing factor that is recruited to genes during transcriptional activation (PubMed:29759984, PubMed:30970244). Recognizes and binds histone H3 without a preference for specific epigenetic markers and also binds DNA (PubMed:20850016, PubMed:30970244). Interacts with KDM1B and promotes its histone demethylase activity by facilitating the capture of H3 tails, they form a multifunctional enzyme complex that modifies transcribed chromatin and facilitates Pol II transcription through nucleosomes (PubMed:23260659, PubMed:29759984, PubMed:30970244). Stimulates the acetylation of 'Lys-56' of nucleosomal histone H3 (H3K56ac) by EP300 (PubMed:29759984). With GATA4, co-binds a defined set of heart development genes and coregulates their expression during cardiomyocyte differentiation (PubMed:35182466). Regulates p38 MAP kinase activity by mediating stress activation of MAPK14/p38alpha and specifically regulating MAPK14 signaling (PubMed:16352664). Indirectly promotes phosphorylation of MAPK14 and activation of ATF2 (PubMed:16352664). The phosphorylation of MAPK14 requires upstream activity of MAP2K4 and MAP2K6 (PubMed:16352664)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"VWA3B":{"coreEvidence":[{"partner":"SIRT1","hgnc":"HGNC:14929","core":true,"core_annotation":{"hgnc":"HGNC:14929","symbol_at_source":"SIRT1","accession":"Q96EB6","function":"Histone modification erase, Histone modification write cofactor","target":"histone","pmids":["15469825"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":398,"hub_weight":0.33407655239053047,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus, PML body; Cytoplasm; Nucleus; Nucleus, nucleoplasm; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"NAD-dependent protein deacetylase that links transcriptional regulation directly to intracellular energetics and participates in the coordination of several separated cellular functions such as cell cycle, response to DNA damage, metabolism, apoptosis and autophagy (PubMed:11672523, PubMed:12006491, PubMed:14976264, PubMed:14980222, PubMed:15126506, PubMed:15152190, PubMed:15205477, PubMed:15469825, PubMed:15692560, PubMed:16079181, PubMed:16166628, PubMed:16892051, PubMed:16998810, PubMed:17283066, PubMed:17290224, PubMed:17334224, PubMed:17505061, PubMed:17612497, PubMed:17620057, PubMed:17936707, PubMed:18203716, PubMed:18296641, PubMed:18662546, PubMed:18687677, PubMed:19188449, PubMed:19220062, PubMed:19364925, PubMed:19690166, PubMed:19934257, PubMed:20097625, PubMed:20100829, PubMed:20203304, PubMed:20375098, PubMed:20620956, PubMed:20670893, PubMed:20817729, PubMed:20955178, PubMed:21149730, PubMed:21245319, PubMed:21471201, PubMed:21504832, PubMed:21555002, PubMed:21698133, PubMed:21701047, PubMed:21775285, PubMed:21807113, PubMed:21841822, PubMed:21890893, PubMed:21947282, PubMed:22274616, PubMed:22918831, PubMed:24415752, PubMed:24824780, PubMed:29681526, PubMed:29765047, PubMed:30409912). Can modulate chromatin function through deacetylation of histones and can promote alterations in the methylation of histones and DNA, leading to transcriptional repression (PubMed:15469825). Deacetylates a broad range of transcription factors and coregulators, thereby regulating target gene expression positively and negatively (PubMed:14976264, PubMed:14980222, PubMed:15152190). Serves as a sensor of the cytosolic ratio of NAD(+)/NADH which is altered by glucose deprivation and metabolic changes associated with caloric restriction (PubMed:15205477). Is essential in skeletal muscle cell differentiation and in response to low nutrients mediates the inhibitory effect on skeletal myoblast differentiation which also involves 5'-AMP-activated protein kinase (AMPK) and nicotinamide phosphoribosyltransferase (NAMPT) (By similarity). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871, PubMed:21504832). Deacetylates 'Lys-266' of SUV39H1, leading to its activation (PubMed:21504832). Inhibits skeletal muscle differentiation by deacetylating PCAF and MYOD1 (PubMed:19188449). Deacetylates H2A and 'Lys-26' of H1-4 (PubMed:15469825). Deacetylates 'Lys-16' of histone H4 (in vitro). Involved in NR0B2/SHP corepression function through chromatin remodeling: Recruited to LRH1 target gene promoters by NR0B2/SHP thereby stimulating histone H3 and H4 deacetylation leading to transcriptional repression (PubMed:20375098). Proposed to contribute to genomic integrity via positive regulation of telomere length; however, reports on localization to pericentromeric heterochromatin are conflicting (By similarity). Proposed to play a role in constitutive heterochromatin (CH) formation and/or maintenance through regulation of the available pool of nuclear SUV39H1 (PubMed:15469825, PubMed:18004385). Upon oxidative/metabolic stress decreases SUV39H1 degradation by inhibiting SUV39H1 polyubiquitination by MDM2 (PubMed:18004385, PubMed:21504832). This increase in SUV39H1 levels enhances SUV39H1 turnover in CH, which in turn seems to accelerate renewal of the heterochromatin which correlates with greater genomic integrity during stress response (PubMed:18004385, PubMed:21504832). Deacetylates 'Lys-382' of p53/TP53 and impairs its ability to induce transcription-dependent proapoptotic program and modulate cell senescence (PubMed:11672523, PubMed:12006491, PubMed:22542455). Deacetylates TAF1B and thereby represses rDNA transcription by the RNA polymerase I (By similarity). Deacetylates MYC, promotes the association of MYC with MAX and decreases MYC stability leading to compromised transformational capability (PubMed:19364925, PubMed:21807113). Deacetylates FOXO3 in response to oxidative stress thereby increasing its ability to induce cell cycle arrest and resistance to oxidative stress but inhibiting FOXO3-mediated induction of apoptosis transcriptional activity; also leading to FOXO3 ubiquitination and protesomal degradation (PubMed:14976264, PubMed:14980222, PubMed:21841822). Appears to have a similar effect on MLLT7/FOXO4 in regulation of transcriptional activity and apoptosis (PubMed:15126506). Deacetylates DNMT1; thereby impairs DNMT1 methyltransferase-independent transcription repressor activity, modulates DNMT1 cell cycle regulatory function and DNMT1-mediated gene silencing (PubMed:21947282). Deacetylates RELA/NF-kappa-B p65 thereby inhibiting its transactivating potential and augments apoptosis in response to TNF (PubMed:15152190). Deacetylates HIF1A, KAT5/TIP60, RB1 and HIC1 (PubMed:17283066, PubMed:17620057, PubMed:20100829, PubMed:20620956). Deacetylates FOXO1 resulting in its nuclear retention and enhancement of its transcriptional activity leading to increased gluconeogenesis in liver (PubMed:15692560). Inhibits E2F1 transcriptional activity and apoptotic function, possibly by deacetylation (PubMed:16892051). Involved in HES1- and HEY2-mediated transcriptional repression (PubMed:12535671). In cooperation with MYCN seems to be involved in transcriptional repression of DUSP6/MAPK3 leading to MYCN stabilization by phosphorylation at 'Ser-62' (PubMed:21698133). Deacetylates MEF2D (PubMed:16166628). Required for antagonist-mediated transcription suppression of AR-dependent genes which may be linked to local deacetylation of histone H3 (PubMed:17505061). Represses HNF1A-mediated transcription (By similarity). Required for the repression of ESRRG by CREBZF (PubMed:19690166). Deacetylates NR1H3 and NR1H2 and deacetylation of NR1H3 at 'Lys-434' positively regulates transcription of NR1H3:RXR target genes, promotes NR1H3 proteasomal degradation and results in cholesterol efflux; a promoter clearing mechanism after reach round of transcription is proposed (PubMed:17936707). Involved in lipid metabolism: deacetylates LPIN1, thereby inhibiting diacylglycerol synthesis (PubMed:20817729, PubMed:29765047). Implicated in regulation of adipogenesis and fat mobilization in white adipocytes by repression of PPARG which probably involves association with NCOR1 and SMRT/NCOR2 (By similarity). Deacetylates p300/EP300 and PRMT1 (By similarity). Deacetylates ACSS2 leading to its activation, and HMGCS1 deacetylation (PubMed:21701047). Involved in liver and muscle metabolism. Through deacetylation and activation of PPARGC1A is required to activate fatty acid oxidation in skeletal muscle under low-glucose conditions and is involved in glucose homeostasis (PubMed:23142079). Involved in regulation of PPARA and fatty acid beta-oxidation in liver. Involved in positive regulation of insulin secretion in pancreatic beta cells in response to glucose; the function seems to imply transcriptional repression of UCP2. Proposed to deacetylate IRS2 thereby facilitating its insulin-induced tyrosine phosphorylation. Deacetylates SREBF1 isoform SREBP-1C thereby decreasing its stability and transactivation in lipogenic gene expression (PubMed:17290224, PubMed:20817729). Involved in DNA damage response by repressing genes which are involved in DNA repair, such as XPC and TP73, deacetylating XRCC6/Ku70, and facilitating recruitment of additional factors to sites of damaged DNA, such as SIRT1-deacetylated NBN can recruit ATM to initiate DNA repair and SIRT1-deacetylated XPA interacts with RPA2 (PubMed:15205477, PubMed:16998810, PubMed:17334224, PubMed:17612497, PubMed:20670893, PubMed:21149730). Also involved in DNA repair of DNA double-strand breaks by homologous recombination and specifically single-strand annealing independently of XRCC6/Ku70 and NBN (PubMed:15205477, PubMed:17334224, PubMed:20097625). Promotes DNA double-strand breaks by mediating deacetylation of SIRT6 (PubMed:32538779). Transcriptional suppression of XPC probably involves an E2F4:RBL2 suppressor complex and protein kinase B (AKT) signaling. Transcriptional suppression of TP73 probably involves E2F4 and PCAF. Deacetylates WRN thereby regulating its helicase and exonuclease activities and regulates WRN nuclear translocation in response to DNA damage (PubMed:18203716). Deacetylates APEX1 at 'Lys-6' and 'Lys-7' and stimulates cellular AP endonuclease activity by promoting the association of APEX1 to XRCC1 (PubMed:19934257). Catalyzes deacetylation of ERCC4/XPF, thereby impairing interaction with ERCC1 and nucleotide excision repair (NER) (PubMed:32034146). Increases p53/TP53-mediated transcription-independent apoptosis by blocking nuclear translocation of cytoplasmic p53/TP53 and probably redirecting it to mitochondria. Deacetylates XRCC6/Ku70 at 'Lys-539' and 'Lys-542' causing it to sequester BAX away from mitochondria thereby inhibiting stress-induced apoptosis. Is involved in autophagy, presumably by deacetylating ATG5, ATG7 and MAP1LC3B/ATG8 (PubMed:18296641). Deacetylates AKT1 which leads to enhanced binding of AKT1 and PDK1 to PIP3 and promotes their activation (PubMed:21775285). Acts as a regulator of AMPK activity in response to calorie restriction: deacetylates the ATP6V1E1 subunit of the V-ATPase complex following activation by TULP3, leading to (1) V-ATPase complex inhibition on lysosomes and (2) AMPK activation via the AXIN1-STK11/LKB1 axis (By similarity). Proposed to play role in regulation of STK11/LBK1-dependent AMPK signaling pathways implicated in cellular senescence which seems to involve the regulation of the acetylation status of STK11/LBK1. Can deacetylate STK11/LBK1 and thereby increase its activity, cytoplasmic localization and association with STRAD; however, the relevance of such activity in normal cells is unclear (PubMed:18687677, PubMed:20203304). In endothelial cells is shown to inhibit STK11/LBK1 activity and to promote its degradation. Deacetylates SMAD7 at 'Lys-64' and 'Lys-70' thereby promoting its degradation. Deacetylates CIITA and augments its MHC class II transactivation and contributes to its stability (PubMed:21890893). Deacetylates MECOM/EVI1 (PubMed:21555002). Deacetylates PML at 'Lys-487' and this deacetylation promotes PML control of PER2 nuclear localization (PubMed:22274616). During the neurogenic transition, represses selective NOTCH1-target genes through histone deacetylation in a BCL6-dependent manner and leading to neuronal differentiation. Regulates the circadian expression of several core clock genes, including BMAL1, RORC, PER2 and CRY1 and plays a critical role in maintaining a controlled rhythmicity in histone acetylation, thereby contributing to circadian chromatin remodeling (PubMed:18662546). Deacetylates BMAL1 and histones at the circadian gene promoters in order to facilitate repression by inhibitory components of the circadian oscillator (By similarity). Deacetylates PER2, facilitating its ubiquitination and degradation by the proteasome (By similarity). Protects cardiomyocytes against palmitate-induced apoptosis (By similarity). Deacetylates XBP1 isoform 2; deacetylation decreases protein stability of XBP1 isoform 2 and inhibits its transcriptional activity (PubMed:20955178). Deacetylates PCK1 and directs its activity toward phosphoenolpyruvate production promoting gluconeogenesis (PubMed:30193097). Involved in the CCAR2-mediated regulation of PCK1 and NR1D1 (PubMed:24415752). Deacetylates CTNB1 at 'Lys-49' (PubMed:24824780). In POMC (pro-opiomelanocortin) neurons, required for leptin-induced activation of PI3K signaling (By similarity). Deacetylates SOX9; promoting SOX9 nuclear localization and transactivation activity (By similarity). Involved in the regulation of centrosome duplication: deacetylates CENATAC in G1 phase, allowing for SASS6 accumulation on the centrosome and subsequent procentriole assembly (PubMed:31722219). Deacetylates NDC80/HEC1 (PubMed:30409912). In addition to protein deacetylase activity, also acts as a protein-lysine deacylase by mediating protein delactylation, depropionylation and decrotonylation (PubMed:28497810, PubMed:38512451). Mediates depropionylation of Osterix (SP7) (By similarity). Catalyzes decrotonylation of histones; it however does not represent a major histone decrotonylase (PubMed:28497810). Mediates protein delactylation of TEAD1 and YAP1 (PubMed:38512451)\nDeacetylates 'Lys-382' of p53/TP53, however with lower activity than isoform 1. In combination, the two isoforms exert an additive effect. Isoform 2 regulates p53/TP53 expression and cellular stress response and is in turn repressed by p53/TP53 presenting a SIRT1 isoform-dependent auto-regulatory loop\nCatalytically inactive 75SirT1 may be involved in regulation of apoptosis. May be involved in protecting chondrocytes from apoptotic death by associating with cytochrome C and interfering with apoptosome assembly\n(Microbial infection) In case of HIV-1 infection, interacts with and deacetylates the viral Tat protein. The viral Tat protein inhibits SIRT1 deacetylation activity toward RELA/NF-kappa-B p65, thereby potentiates its transcriptional activity and SIRT1 is proposed to contribute to T-cell hyperactivation during infection","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LMNTD1":{"coreEvidence":[{"partner":"BRCA1","hgnc":"HGNC:1100","core":true,"core_annotation":{"hgnc":"HGNC:1100","symbol_at_source":"BRCA1","accession":"P38398","function":"Histone modification write cofactor, TF","target":"DNA","pmids":["20820192"],"complexes":"BRCC, BRCA1-A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":965,"hub_weight":0.22194838080923765,"quality":0.75,"programmes":["pubmed:25184681"],"pmids":["25184681"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm; Cytoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that specifically mediates the formation of 'Lys-6'-linked polyubiquitin chains and plays a central role in DNA repair by facilitating cellular responses to DNA damage (PubMed:10500182, PubMed:12887909, PubMed:12890688, PubMed:14976165, PubMed:16818604, PubMed:17525340, PubMed:19261748). It is unclear whether it also mediates the formation of other types of polyubiquitin chains (PubMed:12890688). The BRCA1-BARD1 heterodimer coordinates a diverse range of cellular pathways such as DNA damage repair, ubiquitination and transcriptional regulation to maintain genomic stability (PubMed:12890688, PubMed:14976165, PubMed:20351172). Regulates centrosomal microtubule nucleation (PubMed:18056443). Required for appropriate cell cycle arrests after ionizing irradiation in both the S-phase and the G2 phase of the cell cycle (PubMed:10724175, PubMed:11836499, PubMed:12183412, PubMed:19261748). Required for FANCD2 targeting to sites of DNA damage (PubMed:12887909). Inhibits lipid synthesis by binding to inactive phosphorylated ACACA and preventing its dephosphorylation (PubMed:16326698). Contributes to homologous recombination repair (HRR) via its direct interaction with PALB2, fine-tunes recombinational repair partly through its modulatory role in the PALB2-dependent loading of BRCA2-RAD51 repair machinery at DNA breaks (PubMed:19369211). Component of the BRCA1-RBBP8 complex which regulates CHEK1 activation and controls cell cycle G2/M checkpoints on DNA damage via BRCA1-mediated ubiquitination of RBBP8 (PubMed:16818604). Acts as a transcriptional activator (PubMed:20160719)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LRRC73":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"BRCC3","hgnc":"HGNC:24185","core":true,"core_annotation":{"hgnc":"HGNC:24185","symbol_at_source":"BRCC3","accession":"P46736","function":"Histone modification erase","target":"histone","pmids":["19202061"],"complexes":"BRISC, BRCA1-A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":108,"hub_weight":0.562543950463012,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Cytoplasm; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Metalloprotease that specifically cleaves 'Lys-63'-linked polyubiquitin chains (PubMed:19214193, PubMed:20656690, PubMed:24075985, PubMed:26344097). Does not have activity toward 'Lys-48'-linked polyubiquitin chains (PubMed:19214193, PubMed:20656690, PubMed:24075985, PubMed:26344097). Component of the BRCA1-A complex, a complex that specifically recognizes 'Lys-63'-linked ubiquitinated histones H2A and H2AX at DNA lesions sites, leading to target the BRCA1-BARD1 heterodimer to sites of DNA damage at double-strand breaks (DSBs) (PubMed:14636569, PubMed:16707425, PubMed:17525341, PubMed:19202061, PubMed:19261746, PubMed:19261748, PubMed:19261749). In the BRCA1-A complex, it specifically removes 'Lys-63'-linked ubiquitin on histones H2A and H2AX, antagonizing the RNF8-dependent ubiquitination at double-strand breaks (DSBs) (PubMed:20656690). Catalytic subunit of the BRISC complex, a multiprotein complex that specifically cleaves 'Lys-63'-linked ubiquitin in various substrates (PubMed:20656690, PubMed:24075985, PubMed:26195665, PubMed:26344097). Mediates the specific 'Lys-63'-specific deubiquitination associated with the COP9 signalosome complex (CSN), via the interaction of the BRISC complex with the CSN complex (PubMed:19214193). The BRISC complex is required for normal mitotic spindle assembly and microtubule attachment to kinetochores via its role in deubiquitinating NUMA1 (PubMed:26195665). Plays a role in interferon signaling via its role in the deubiquitination of the interferon receptor IFNAR1; deubiquitination increases IFNAR1 activity by enhancing its stability and cell surface expression (PubMed:24075985, PubMed:26344097). Acts as a regulator of the NLRP3 inflammasome by mediating deubiquitination of NLRP3, leading to NLRP3 inflammasome assembly (By similarity). Down-regulates the response to bacterial lipopolysaccharide (LPS) via its role in IFNAR1 deubiquitination (PubMed:24075985). Deubiquitinates HDAC1 and PWWP2B leading to their stabilization (By similarity)","source":"project UniProt records20261017/18"},{"partner":"ABRAXAS2","hgnc":"HGNC:28975","core":true,"core_annotation":{"hgnc":"HGNC:28975","symbol_at_source":"FAM175B","accession":"Q15018","function":"Histone modification erase cofactor","target":"histone","pmids":["20656690"],"complexes":"BRISC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":92,"hub_weight":0.5933908290969266,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Cytoplasm; Nucleus; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the BRISC complex, a multiprotein complex that specifically cleaves 'Lys-63'-linked polyubiquitin, leaving the last ubiquitin chain attached to its substrates (PubMed:19214193, PubMed:20032457, PubMed:20656690, PubMed:24075985). May act as a central scaffold protein that assembles the various components of the BRISC complex and retains them in the cytoplasm (PubMed:20656690). Plays a role in regulating the onset of apoptosis via its role in modulating 'Lys-63'-linked ubiquitination of target proteins (By similarity). Required for normal mitotic spindle assembly and microtubule attachment to kinetochores via its role in deubiquitinating NUMA1 (PubMed:26195665). Plays a role in interferon signaling via its role in the deubiquitination of the interferon receptor IFNAR1; deubiquitination increases IFNAR1 activities by enhancing its stability and cell surface expression (PubMed:24075985, PubMed:26344097). Down-regulates the response to bacterial lipopolysaccharide (LPS) via its role in IFNAR1 deubiquitination (PubMed:24075985). Required for normal induction of p53/TP53 in response to DNA damage (PubMed:25283148). Independent of the BRISC complex, promotes interaction between USP7 and p53/TP53, and thereby promotes deubiquitination of p53/TP53, preventing its degradation and resulting in increased p53/TP53-mediated transcription regulation and p53/TP53-dependent apoptosis in response to DNA damage (PubMed:25283148)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"C1orf21":{"coreEvidence":[{"partner":"MTA2","hgnc":"HGNC:7411","core":true,"core_annotation":{"hgnc":"HGNC:7411","symbol_at_source":"MTA2","accession":"O94776","function":"Histone modification erase cofactor","target":"histone","pmids":["10444591"],"complexes":"NuRD","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":427,"hub_weight":0.32376195411908804,"quality":0.65,"programmes":["pubmed:40437099"],"pmids":["40437099"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May function as a transcriptional coregulator (PubMed:16428440, PubMed:28977666). Acts as a component of the histone deacetylase NuRD complex which participates in the remodeling of chromatin (PubMed:16428440, PubMed:28977666)","source":"project UniProt records20261017/18"},{"partner":"PPP2CA","hgnc":"HGNC:9299","core":true,"core_annotation":{"hgnc":"HGNC:9299","symbol_at_source":"PPP2CA","accession":"P67775","function":"Histone modification write","target":"histone","pmids":["18758438"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":348,"hub_weight":0.3544406025041679,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus; Chromosome; Chromosome, centromere; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of protein phosphatase 2A (PP2A), a serine/threonine phosphatase involved in the regulation of a wide variety of enzymes, signal transduction pathways, and cellular events (PubMed:10801873, PubMed:12473674, PubMed:17245430, PubMed:22613722, PubMed:33243860, PubMed:34004147, PubMed:9920888, PubMed:41986709). PP2A is the major phosphatase for microtubule-associated proteins (MAPs) (PubMed:22613722). PP2A can modulate the activity of phosphorylase B kinase casein kinase 2, mitogen-stimulated S6 kinase, and MAP-2 kinase (PubMed:22613722). Cooperates with SGO2 to protect centromeric cohesin from separase-mediated cleavage in oocytes specifically during meiosis I (By similarity). Can dephosphorylate various proteins, such as SV40 large T antigen, AXIN1, p53/TP53, PIM3, WEE1 (PubMed:10801873, PubMed:12473674, PubMed:17245430, PubMed:9920888). Activates RAF1 by dephosphorylating it at 'Ser-259' (PubMed:10801873). Mediates dephosphorylation of WEE1, preventing its ubiquitin-mediated proteolysis, increasing WEE1 protein levels, and promoting the G2/M checkpoint (PubMed:33108758). Mediates dephosphorylation of MYC; promoting its ubiquitin-mediated proteolysis: interaction with AMBRA1 enhances interaction between PPP2CA and MYC (PubMed:25438055). Mediates dephosphorylation of FOXO3; promoting its stabilization: interaction with AMBRA1 enhances interaction between PPP2CA and FOXO3 (PubMed:30513302). Catalyzes dephosphorylation of the pyrin domain of NLRP3, promoting assembly of the NLRP3 inflammasome (By similarity). Together with RACK1 adapter, mediates dephosphorylation of AKT1 at 'Ser-473', preventing AKT1 activation and AKT-mTOR signaling pathway (By similarity). Dephosphorylation of AKT1 is essential for regulatory T-cells (Treg) homeostasis and stability (By similarity). Catalyzes dephosphorylation of PIM3, promoting PIM3 ubiquitination and proteasomal degradation (PubMed:12473674). Part of the striatin-interacting phosphatase and kinase (STRIPAK) complexes (PubMed:33633399). STRIPAK complexes have critical roles in protein (de)phosphorylation and are regulators of multiple signaling pathways including Hippo, MAPK, nuclear receptor and cytoskeleton remodeling (PubMed:33633399). Different types of STRIPAK complexes are involved in a variety of biological processes such as cell growth, differentiation, apoptosis, metabolism and immune regulation (PubMed:33633399). Key mediator of a quality checkpoint during transcription elongation as part of the Integrator-PP2A (INTAC) complex (PubMed:33243860, PubMed:34004147, PubMed:37080207). The INTAC complex drives premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation: within the INTAC complex, PPP2CA catalyzes dephosphorylation of the C-terminal domain (CTD) of Pol II subunit POLR2A/RPB1 and SUPT5H/SPT5, thereby preventing transcriptional elongation (PubMed:33243860, PubMed:34004147, PubMed:37080207)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FAM234A":{"coreEvidence":[{"partner":"ATM","hgnc":"HGNC:795","core":true,"core_annotation":{"hgnc":"HGNC:795","symbol_at_source":"ATM","accession":"Q13315","function":"Histone modification write","target":"histone","pmids":["19261749"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":263,"hub_weight":0.39968038348871576,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasmic vesicle; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Peroxisome matrix","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine protein kinase which activates checkpoint signaling upon double strand breaks (DSBs), apoptosis and genotoxic stresses such as ionizing ultraviolet A light (UVA), thereby acting as a DNA damage sensor (PubMed:10550055, PubMed:10839545, PubMed:10910365, PubMed:12556884, PubMed:14871926, PubMed:15064416, PubMed:15448695, PubMed:15456891, PubMed:15790808, PubMed:15916964, PubMed:17923702, PubMed:21757780, PubMed:24534091, PubMed:27941124, PubMed:35076389, PubMed:9733514). Recognizes the substrate consensus sequence [ST]-Q (PubMed:10550055, PubMed:10839545, PubMed:10910365, PubMed:12556884, PubMed:14871926, PubMed:15448695, PubMed:15456891, PubMed:15916964, PubMed:17923702, PubMed:24534091, PubMed:27941124, PubMed:9733514). Phosphorylates 'Ser-139' of histone variant H2AX at double strand breaks (DSBs), thereby regulating DNA damage response mechanism (By similarity). Also plays a role in pre-B cell allelic exclusion, a process leading to expression of a single immunoglobulin heavy chain allele to enforce clonality and monospecific recognition by the B-cell antigen receptor (BCR) expressed on individual B-lymphocytes. After the introduction of DNA breaks by the RAG complex on one immunoglobulin allele, acts by mediating a repositioning of the second allele to pericentromeric heterochromatin, preventing accessibility to the RAG complex and recombination of the second allele. Also involved in signal transduction and cell cycle control. May function as a tumor suppressor. Necessary for activation of ABL1 and SAPK. Phosphorylates DYRK2, CHEK2, p53/TP53, FBXW7, FANCD2, NFKBIA, BRCA1, CREBBP/CBP, RBBP8/CTIP, FBXO46, MRE11, nibrin (NBN), RAD50, RAD17, PELI1, TERF1, UFL1, RAD9, UBQLN4, UCHL3 and DCLRE1C (PubMed:10550055, PubMed:10766245, PubMed:10802669, PubMed:10839545, PubMed:10910365, PubMed:10973490, PubMed:11375976, PubMed:12086603, PubMed:15456891, PubMed:19965871, PubMed:21757780, PubMed:24534091, PubMed:26240375, PubMed:26774286, PubMed:27941124, PubMed:30171069, PubMed:30612738, PubMed:30886146, PubMed:30952868, PubMed:38128537, PubMed:9733515, PubMed:9843217). May play a role in vesicle and/or protein transport. Could play a role in T-cell development, gonad and neurological function. Plays a role in replication-dependent histone mRNA degradation. Binds DNA ends. Phosphorylation of DYRK2 in nucleus in response to genotoxic stress prevents its MDM2-mediated ubiquitination and subsequent proteasome degradation (PubMed:19965871). Phosphorylates ATF2 which stimulates its function in DNA damage response (PubMed:15916964). Phosphorylates ERCC6 which is essential for its chromatin remodeling activity at DNA double-strand breaks (PubMed:29203878). Phosphorylates TTC5/STRAP at 'Ser-203' in the cytoplasm in response to DNA damage, which promotes TTC5/STRAP nuclear localization (PubMed:15448695). Also involved in pexophagy by mediating phosphorylation of PEX5: translocated to peroxisomes in response to reactive oxygen species (ROS), and catalyzes phosphorylation of PEX5, promoting PEX5 ubiquitination and induction of pexophagy (PubMed:26344566)","source":"project UniProt records20261017/18"},{"partner":"ATR","hgnc":"HGNC:882","core":true,"core_annotation":{"hgnc":"HGNC:882","symbol_at_source":"ATR","accession":"Q13535","function":"Histone modification write","target":"histone","pmids":["11673449"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":530,"hub_weight":0.29361010975735174,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Nucleus envelope","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine protein kinase which activates checkpoint signaling upon genotoxic stresses such as ionizing radiation (IR), ultraviolet light (UV), or DNA replication stalling, thereby acting as a DNA damage sensor (PubMed:10597277, PubMed:10608806, PubMed:10859164, PubMed:11721054, PubMed:12791985, PubMed:12814551, PubMed:14657349, PubMed:14729973, PubMed:14742437, PubMed:15210935, PubMed:15496423, PubMed:16260606, PubMed:21144835, PubMed:21777809, PubMed:23273981, PubMed:25083873, PubMed:27723717, PubMed:27723720, PubMed:30139873, PubMed:33848395, PubMed:37788673, PubMed:37832547, PubMed:9427750, PubMed:9636169). Recognizes the substrate consensus sequence [ST]-Q (PubMed:10597277, PubMed:10608806, PubMed:10859164, PubMed:11721054, PubMed:12791985, PubMed:12814551, PubMed:14657349, PubMed:14729973, PubMed:14742437, PubMed:15210935, PubMed:15496423, PubMed:16260606, PubMed:21144835, PubMed:23273981, PubMed:27723717, PubMed:27723720, PubMed:33848395, PubMed:9427750, PubMed:9636169). Phosphorylates BRCA1, CHEK1, MCM2, RAD17, RBBP8, RPA2, SMC1 and p53/TP53, which collectively inhibit DNA replication and mitosis and promote DNA repair, recombination and apoptosis (PubMed:11114888, PubMed:11418864, PubMed:11865061, PubMed:21777809, PubMed:23273981, PubMed:25083873, PubMed:9925639). Phosphorylates 'Ser-139' of histone variant H2AX at sites of DNA damage, thereby regulating DNA damage response mechanism (PubMed:11673449). Required for FANCD2 ubiquitination (PubMed:15314022). Critical for maintenance of fragile site stability and efficient regulation of centrosome duplication (PubMed:12526805). Acts as a regulator of the S-G2 transition by restricting the activity of CDK1 during S-phase to prevent premature entry into G2 (PubMed:30139873). Acts as a regulator of the nuclear envelope integrity in response to DNA damage and stress (PubMed:25083873, PubMed:37788673, PubMed:37832547). Acts as a mechanical stress sensor at the nuclear envelope: relocalizes to the nuclear envelope in response to mechanical stress and mediates a checkpoint via phosphorylation of CHEK1 (PubMed:25083873). Also promotes nuclear envelope rupture in response to DNA damage by mediating phosphorylation of LMNA at 'Ser-282', leading to lamin disassembly (PubMed:37832547). Involved in the inflammatory response to genome instability and double-stranded DNA breaks: acts by localizing to micronuclei arising from genome instability and catalyzing phosphorylation of LMNA at 'Ser-395', priming LMNA for subsequent phosphorylation by CDK1 and micronuclei envelope rupture (PubMed:37788673). The rupture of micronuclear envelope triggers the cGAS-STING pathway thereby activating the type I interferon response and innate immunity (PubMed:37788673). Positively regulates the restart of stalled replication forks following activation by the KHDC3L-OOEP scaffold complex (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PRKDC","hgnc":"HGNC:9413","core":true,"core_annotation":{"hgnc":"HGNC:9413","symbol_at_source":"PRKDC","accession":"P78527","function":"Histone modification write","target":"histone","pmids":["14627815"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":616,"hub_weight":0.2739983121755955,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase that acts as a molecular sensor for DNA damage (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:33854234). Involved in DNA non-homologous end joining (NHEJ) required for double-strand break (DSB) repair and V(D)J recombination (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:33854234, PubMed:34352203). Must be bound to DNA to express its catalytic properties (PubMed:11955432). Promotes processing of hairpin DNA structures in V(D)J recombination by activation of the hairpin endonuclease artemis (DCLRE1C) (PubMed:11955432). Recruited by XRCC5 and XRCC6 to DNA ends and is required to (1) protect and align broken ends of DNA, thereby preventing their degradation, (2) and sequester the DSB for repair by NHEJ (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326, PubMed:33854234). Acts as a scaffold protein to aid the localization of DNA repair proteins to the site of damage (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). The assembly of the DNA-PK complex at DNA ends is also required for the NHEJ ligation step (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). Found at the ends of chromosomes, suggesting a further role in the maintenance of telomeric stability and the prevention of chromosomal end fusion (By similarity). Also involved in modulation of transcription (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). As part of the DNA-PK complex, involved in the early steps of ribosome assembly by promoting the processing of precursor rRNA into mature 18S rRNA in the small-subunit processome (PubMed:32103174). Binding to U3 small nucleolar RNA, recruits PRKDC and XRCC5/Ku86 to the small-subunit processome (PubMed:32103174). Recognizes the substrate consensus sequence [ST]-Q (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). Phosphorylates 'Ser-139' of histone variant H2AX, thereby regulating DNA damage response mechanism (PubMed:14627815, PubMed:16046194). Phosphorylates ASF1A, DCLRE1C, c-Abl/ABL1, histone H1, HSPCA, c-jun/JUN, p53/TP53, PARP1, POU2F1, DHX9, FH, SRF, NHEJ1/XLF, XRCC1, XRCC4, XRCC5, XRCC6, WRN, MYC and RFA2 (PubMed:10026262, PubMed:10467406, PubMed:11889123, PubMed:12509254, PubMed:14599745, PubMed:14612514, PubMed:14704337, PubMed:15177042, PubMed:1597196, PubMed:16397295, PubMed:18644470, PubMed:2247066, PubMed:2507541, PubMed:26237645, PubMed:26666690, PubMed:28712728, PubMed:29478807, PubMed:30247612, PubMed:8407951, PubMed:8464713, PubMed:9139719, PubMed:9362500). Can phosphorylate C1D not only in the presence of linear DNA but also in the presence of supercoiled DNA (PubMed:9679063). Ability to phosphorylate p53/TP53 in the presence of supercoiled DNA is dependent on C1D (PubMed:9363941). Acts as a regulator of the phosphatidylinositol 3-kinase/protein kinase B signal transduction by mediating phosphorylation of 'Ser-473' of protein kinase B (PKB/AKT1, PKB/AKT2, PKB/AKT3), promoting their activation (PubMed:15262962). Contributes to the determination of the circadian period length by antagonizing phosphorylation of CRY1 'Ser-588' and increasing CRY1 protein stability, most likely through an indirect mechanism (By similarity). Plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728). Also regulates the cGAS-STING pathway by catalyzing phosphorylation of CGAS, thereby impairing CGAS oligomerization and activation (PubMed:33273464). Also regulates the cGAS-STING pathway by mediating phosphorylation of PARP1 (PubMed:35460603)","source":"project UniProt records20261017/18"},{"partner":"USP22","hgnc":"HGNC:12621","core":true,"core_annotation":{"hgnc":"HGNC:12621","symbol_at_source":"USP22","accession":"Q9UPT9","function":"Histone modification write cofactor","target":"histone","pmids":["18469533"],"complexes":"SAGA","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":122,"hub_weight":0.5391638660171921,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinase that plays a role in several cellular processes including transcriptional regulation, cell cycle progression or innate immunity. As part of the transcription regulatory histone acetylation (HAT) complex SAGA, catalyzes the deubiquitination of both histones H2A and H2B, thereby acting as a transcriptional coactivator (PubMed:18206972, PubMed:18206973, PubMed:18469533). Recruited to specific gene promoters by activators such as MYC, where it is required for transcription. Facilitates cell-cycle progression by stabilizing CCNB1 and antagonizing its proteasome-mediated degradation in a cell cycle-specific manner (PubMed:27030811). Modulates cell cycle progression and apoptosis also by antagonizing TP53 transcriptional activation through deacetylase SIRT1 stabilization (PubMed:22542455). Plays multiple roles in immunity and inflammation. Participates in antiviral response by deubiquitinating the importin KPNA2, leading to IRF3 nuclear translocation and subsequent type I interferon production (PubMed:32130408). Acts as a central regulator of type III IFN signaling by negatively regulating STING1 activation and ubiquitination (PubMed:35933402). Inhibits NLRP3 inflammasome activation by promoting NLRP3 degradation through ATG5-dependent autophagy (By similarity). Deubiquitinates CD274 to induce its stabilization and thereby participates in maintenance of immune tolerance to self (PubMed:31399419). Controls necroptotic cell death by regulating RIPK3 phosphorylation and ubiquitination (PubMed:33369872). During bacterial infection, promotes pro-inflammatory response by targeting TRAF6 and removing its 'Lys-48'-linked polyubiquitination (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"VPS9D1":{"coreEvidence":[{"partner":"TRIM27","hgnc":"HGNC:9975","core":true,"core_annotation":{"hgnc":"HGNC:9975","symbol_at_source":"TRIM27","accession":"P14373","function":"Histone modification erase cofactor","target":"#","pmids":["19351825"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":414,"hub_weight":0.32826608214930636,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Early endosome; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates ubiquitination of various substrates and thereby plays a role in diffent processes including proliferation, innate immunity, apoptosis, immune response or autophagy (PubMed:22829933, PubMed:24144979, PubMed:29688809, PubMed:36111389). Ubiquitinates PIK3C2B and inhibits its activity by mediating the formation of 'Lys-48'-linked polyubiquitin chains; the function inhibits CD4 T-cell activation. Acts as a regulator of retrograde transport: together with MAGEL2, mediates the formation of 'Lys-63'-linked polyubiquitin chains at 'Lys-220' of WASHC1, leading to promote endosomal F-actin assembly (PubMed:23452853). Has a transcriptional repressor activity by cooperating with EPC1. Induces apoptosis by activating Jun N-terminal kinase and p38 kinase and also increases caspase-3-like activity independently of mitochondrial events. May function in male germ cell development. Has DNA-binding activity and preferentially bound to double-stranded DNA. Forms a complex with and ubiquitinates the ubiquitin-specific protease USP7, which in turn deubiquitinates RIPK1 resulting in the positive regulation of TNF-induced apoptosis (PubMed:24144979). In addition, acts with USP7 or PTPN11 as an inhibitor of the antiviral signaling pathway by promoting kinase TBK1 ubiquitination and degradation (PubMed:26358190, PubMed:29688809). Acts as a negative regulator of NOD2 signaling by mediating ubiquitination of NOD2, promoting its degradation by the proteasome (PubMed:22829933). Alternatively, facilitates mitophagy via stabilization of active TBK1 (PubMed:36111389). Negatively regulates autophagy flux under basal conditions by directly polyubiquitinating ULK1 (PubMed:35670107). During starvation-induced autophagy, catalyzes non-degradative ubiquitination of the kinase STK38L promoting its activation and phosphorylation of ULK1 leading to its ubiquitination and degradation to restrain the amplitude and duration of autophagy (PubMed:35670107)\n(Microbial infection) Positively regulates hepatitis C virus replication by suppressing type I IFN response during infection","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LYSMD2":{"coreEvidence":[{"partner":"PRKCD","hgnc":"HGNC:9399","core":true,"core_annotation":{"hgnc":"HGNC:9399","symbol_at_source":"PRKCD","accession":"Q05655","function":"Histone modification","target":"histone","pmids":["17984964"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":113,"hub_weight":0.5538487756217113,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HeLa epitheloid cervical carcinoma cell\", \"human-hela\"]"],"partner_location":"Cytoplasm; Cytoplasm, perinuclear region; Nucleus; Cell membrane; Mitochondrion; Endomembrane system","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Calcium-independent, phospholipid- and diacylglycerol (DAG)-dependent serine/threonine-protein kinase that plays contrasting roles in cell death and cell survival by functioning as a pro-apoptotic protein during DNA damage-induced apoptosis, but acting as an anti-apoptotic protein during cytokine receptor-initiated cell death, is involved in tumor suppression as well as survival of several cancers, is required for oxygen radical production by NADPH oxidase and acts as positive or negative regulator in platelet functional responses (PubMed:21406692, PubMed:21810427). Negatively regulates B cell proliferation and also has an important function in self-antigen induced B cell tolerance induction (By similarity). Upon DNA damage, activates the promoter of the death-promoting transcription factor BCLAF1/Btf to trigger BCLAF1-mediated p53/TP53 gene transcription and apoptosis (PubMed:21406692, PubMed:21810427). In response to oxidative stress, interact with and activate CHUK/IKKA in the nucleus, causing the phosphorylation of p53/TP53 (PubMed:21406692, PubMed:21810427). In the case of ER stress or DNA damage-induced apoptosis, can form a complex with the tyrosine-protein kinase ABL1 which trigger apoptosis independently of p53/TP53 (PubMed:21406692, PubMed:21810427). In cytosol can trigger apoptosis by activating MAPK11 or MAPK14, inhibiting AKT1 and decreasing the level of X-linked inhibitor of apoptosis protein (XIAP), whereas in nucleus induces apoptosis via the activation of MAPK8 or MAPK9. Upon ionizing radiation treatment, is required for the activation of the apoptosis regulators BAX and BAK, which trigger the mitochondrial cell death pathway. Can phosphorylate MCL1 and target it for degradation which is sufficient to trigger for BAX activation and apoptosis. Is required for the control of cell cycle progression both at G1/S and G2/M phases. Mediates phorbol 12-myristate 13-acetate (PMA)-induced inhibition of cell cycle progression at G1/S phase by up-regulating the CDK inhibitor CDKN1A/p21 and inhibiting the cyclin CCNA2 promoter activity. In response to UV irradiation can phosphorylate CDK1, which is important for the G2/M DNA damage checkpoint activation (By similarity). Can protect glioma cells from the apoptosis induced by TNFSF10/TRAIL, probably by inducing increased phosphorylation and subsequent activation of AKT1 (PubMed:15774464). Is highly expressed in a number of cancer cells and promotes cell survival and resistance against chemotherapeutic drugs by inducing cyclin D1 (CCND1) and hyperphosphorylation of RB1, and via several pro-survival pathways, including NF-kappa-B, AKT1 and MAPK1/3 (ERK1/2). Involved in antifungal immunity by mediating phosphorylation and activation of CARD9 downstream of C-type lectin receptors activation, promoting interaction between CARD9 and BCL10, followed by activation of NF-kappa-B and MAP kinase p38 pathways (By similarity). Can also act as tumor suppressor upon mitogenic stimulation with PMA or TPA. In N-formyl-methionyl-leucyl-phenylalanine (fMLP)-treated cells, is required for NCF1 (p47-phox) phosphorylation and activation of NADPH oxidase activity, and regulates TNF-elicited superoxide anion production in neutrophils, by direct phosphorylation and activation of NCF1 or indirectly through MAPK1/3 (ERK1/2) signaling pathways (PubMed:19801500). May also play a role in the regulation of NADPH oxidase activity in eosinophil after stimulation with IL5, leukotriene B4 or PMA (PubMed:11748588). In collagen-induced platelet aggregation, acts a negative regulator of filopodia formation and actin polymerization by interacting with and negatively regulating VASP phosphorylation (PubMed:16940418). Downstream of PAR1, PAR4 and CD36/GP4 receptors, regulates differentially platelet dense granule secretion; acts as a positive regulator in PAR-mediated granule secretion, whereas it negatively regulates CD36/GP4-mediated granule release (PubMed:19587372). Phosphorylates MUC1 in the C-terminal and regulates the interaction between MUC1 and beta-catenin (PubMed:11877440). The catalytic subunit phosphorylates 14-3-3 proteins (YWHAB, YWHAZ and YWHAH) in a sphingosine-dependent fashion (By similarity). Phosphorylates ELAVL1 in response to angiotensin-2 treatment (PubMed:18285462). Phosphorylates mitochondrial phospholipid scramblase 3 (PLSCR3), resulting in increased cardiolipin expression on the mitochondrial outer membrane which facilitates apoptosis (PubMed:12649167). Phosphorylates SMPD1 which induces SMPD1 secretion (PubMed:17303575). Acts as a negative regulator of smoothened signaling by mediating phosphorylation of GLI1, preventing its localization to the nucleus (PubMed:19015273). Acts as a regulator of dopamine signaling by mediating constitutive phosphorylation of dopamine receptor DRD1, inhibiting G protein-coupled receptor signaling (PubMed:20969574)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZNF839":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"TP53","hgnc":"HGNC:11998","core":true,"core_annotation":{"hgnc":"HGNC:11998","symbol_at_source":"TP53","accession":"P04637","function":"Histone modification write cofactor, TF","target":"histone","pmids":["23870121"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1691,"hub_weight":0.16946718543287687,"quality":0.75,"programmes":["pubmed:27229929"],"pmids":["27229929"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus, PML body; Endoplasmic reticulum; Mitochondrion matrix; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional transcription factor that induces cell cycle arrest, DNA repair or apoptosis upon binding to its target DNA sequence (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:35618207, PubMed:36634798, PubMed:38653238, PubMed:9840937). Acts as a tumor suppressor in many tumor types; induces growth arrest or apoptosis depending on the physiological circumstances and cell type (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17189187, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:38653238, PubMed:9840937). Negatively regulates cell division by controlling expression of a set of genes required for this process (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:9840937). One of the activated genes is an inhibitor of cyclin-dependent kinases. Apoptosis induction seems to be mediated either by stimulation of BAX and FAS antigen expression, or by repression of Bcl-2 expression (PubMed:12524540, PubMed:17189187). Its pro-apoptotic activity is activated via its interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 (PubMed:12524540). However, this activity is inhibited when the interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 is displaced by PPP1R13L/iASPP (PubMed:12524540). In cooperation with mitochondrial PPIF is involved in activating oxidative stress-induced necrosis; the function is largely independent of transcription. Induces the transcription of long intergenic non-coding RNA p21 (lincRNA-p21) and lincRNA-Mkln1. LincRNA-p21 participates in TP53-dependent transcriptional repression leading to apoptosis and seems to have an effect on cell-cycle regulation. Implicated in Notch signaling cross-over. Prevents CDK7 kinase activity when associated to CAK complex in response to DNA damage, thus stopping cell cycle progression. Isoform 2 enhances the transactivation activity of isoform 1 from some but not all TP53-inducible promoters. Isoform 4 suppresses transactivation activity and impairs growth suppression mediated by isoform 1. Isoform 7 inhibits isoform 1-mediated apoptosis. Regulates the circadian clock by repressing CLOCK-BMAL1-mediated transcriptional activation of PER2 (PubMed:24051492)","source":"project UniProt records20261017/18"},{"partner":"YWHAE","hgnc":"HGNC:12851","core":true,"core_annotation":{"hgnc":"HGNC:12851","symbol_at_source":"YWHAE","accession":"P62258","function":"Histone modification erase cofactor","target":"histone","pmids":["10869435"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":833,"hub_weight":0.23796037813647444,"quality":0.75,"programmes":["pubmed:20936779"],"pmids":["20936779"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Melanosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:21189250). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35343654). Binding generally results in the modulation of the activity of the binding partner (By similarity). Positively regulates phosphorylated protein HSF1 nuclear export to the cytoplasm (PubMed:12917326). Plays a positive role in the antiviral signaling pathway upstream of TBK1 via interaction with RIGI (PubMed:37555661). Mechanistically, directs RIGI redistribution from the cytosol to mitochondrial associated membranes where it mediates MAVS-dependent innate immune signaling during viral infection (PubMed:22607805). Plays a role in proliferation inhibition and cell cycle arrest by exporting HNRNPC from the nucleus to the cytoplasm to be degraded by ubiquitination (PubMed:37599448)","source":"project UniProt records20261017/18"},{"partner":"YWHAZ","hgnc":"HGNC:12855","core":true,"core_annotation":{"hgnc":"HGNC:12855","symbol_at_source":"YWHAZ","accession":"P63104","function":"Histone modification read","target":"histone","pmids":["16246723"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":960,"hub_weight":0.2224970797449924,"quality":0.75,"programmes":["pubmed:20936779"],"pmids":["20936779"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Melanosome","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:14578935, PubMed:15071501, PubMed:15644438, PubMed:16376338, PubMed:16959763, PubMed:31024343, PubMed:9360956). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35662396). Binding generally results in the modulation of the activity of the binding partner (PubMed:35662396). Promotes cytosolic retention and inactivation of TFEB transcription factor by binding to phosphorylated TFEB (PubMed:35662396). Induces ARHGEF7 activity on RAC1 as well as lamellipodia and membrane ruffle formation (PubMed:16959763). In neurons, regulates spine maturation through the modulation of ARHGEF7 activity (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MNMIP1":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"PARP3","hgnc":"HGNC:273","core":true,"core_annotation":{"hgnc":"HGNC:273","symbol_at_source":"PARP3","accession":"Q9Y6F1","function":"Polycomb group (PcG) protein","target":"#","pmids":["16924674"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Mono-ADP-ribosyltransferase that mediates mono-ADP-ribosylation of target proteins and plays a key role in the response to DNA damage (PubMed:16924674, PubMed:19354255, PubMed:20064938, PubMed:21211721, PubMed:21270334, PubMed:23742272, PubMed:24598253, PubMed:25043379, PubMed:28447610). Mediates mono-ADP-ribosylation of glutamate, aspartate or lysine residues on target proteins (PubMed:20064938, PubMed:25043379). In contrast to PARP1 and PARP2, it is not able to mediate poly-ADP-ribosylation (PubMed:25043379). Involved in DNA repair by mediating mono-ADP-ribosylation of a limited number of acceptor proteins involved in chromatin architecture and in DNA metabolism, such as histone H2B, XRCC5 and XRCC6 (PubMed:16924674, PubMed:24598253). ADP-ribosylation follows DNA damage and appears as an obligatory step in a detection/signaling pathway leading to the reparation of DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Involved in single-strand break repair by catalyzing mono-ADP-ribosylation of histone H2B on 'Glu-2' (H2BE2ADPr) of nucleosomes containing nicked DNA (PubMed:27530147). Cooperates with the XRCC5-XRCC6 (Ku80-Ku70) heterodimer to limit end-resection thereby promoting accurate NHEJ (PubMed:24598253). Suppresses G-quadruplex (G4) structures in response to DNA damage (PubMed:28447610). Associates with a number of DNA repair factors and is involved in the response to exogenous and endogenous DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Together with APLF, promotes the retention of the LIG4-XRCC4 complex on chromatin and accelerate DNA ligation during non-homologous end-joining (NHEJ) (PubMed:21211721). May link the DNA damage surveillance network to the mitotic fidelity checkpoint (PubMed:16924674). Acts as a negative regulator of immunoglobulin class switch recombination, probably by controlling the level of AICDA /AID on the chromatin (By similarity). In addition to proteins, also able to ADP-ribosylate DNA: mediates DNA mono-ADP-ribosylation of DNA strand break termini via covalent addition of a single ADP-ribose moiety to a 5'- or 3'-terminal phosphate residues in DNA containing multiple strand breaks (PubMed:29361132, PubMed:29520010)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"EVA1B":{"coreEvidence":[{"partner":"CHUK","hgnc":"HGNC:1974","core":true,"core_annotation":{"hgnc":"HGNC:1974","symbol_at_source":"CHUK","accession":"O15111","function":"Histone modification write","target":"histone","pmids":["17434128"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":158,"hub_weight":0.4902903378454601,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine kinase that plays an essential role in the NF-kappa-B signaling pathway which is activated by multiple stimuli such as inflammatory cytokines, bacterial or viral products, DNA damages or other cellular stresses (PubMed:18626576, PubMed:9244310, PubMed:9252186, PubMed:9346484). Acts as a part of the canonical IKK complex in the conventional pathway of NF-kappa-B activation and phosphorylates inhibitors of NF-kappa-B on serine residues (PubMed:18626576, PubMed:35952808, PubMed:9244310, PubMed:9252186, PubMed:9346484). These modifications allow polyubiquitination of the inhibitors and subsequent degradation by the proteasome (PubMed:18626576, PubMed:9244310, PubMed:9252186, PubMed:9346484). In turn, free NF-kappa-B is translocated into the nucleus and activates the transcription of hundreds of genes involved in immune response, growth control, or protection against apoptosis (PubMed:18626576, PubMed:9244310, PubMed:9252186, PubMed:9346484). Negatively regulates the pathway by phosphorylating the scaffold protein TAXBP1 and thus promoting the assembly of the A20/TNFAIP3 ubiquitin-editing complex (composed of A20/TNFAIP3, TAX1BP1, and the E3 ligases ITCH and RNF11) (PubMed:21765415). Therefore, CHUK plays a key role in the negative feedback of NF-kappa-B canonical signaling to limit inflammatory gene activation. As part of the non-canonical pathway of NF-kappa-B activation, the MAP3K14-activated CHUK/IKKA homodimer phosphorylates NFKB2/p100 associated with RelB, inducing its proteolytic processing to NFKB2/p52 and the formation of NF-kappa-B RelB-p52 complexes (PubMed:20501937). In turn, these complexes regulate genes encoding molecules involved in B-cell survival and lymphoid organogenesis. Also participates in the negative feedback of the non-canonical NF-kappa-B signaling pathway by phosphorylating and destabilizing MAP3K14/NIK. Within the nucleus, phosphorylates CREBBP and consequently increases both its transcriptional and histone acetyltransferase activities (PubMed:17434128). Modulates chromatin accessibility at NF-kappa-B-responsive promoters by phosphorylating histones H3 at 'Ser-10' that are subsequently acetylated at 'Lys-14' by CREBBP (PubMed:12789342). Additionally, phosphorylates the CREBBP-interacting protein NCOA3. Also phosphorylates FOXO3 and may regulate this pro-apoptotic transcription factor (PubMed:15084260). Phosphorylates RIPK1 at 'Ser-25' which represses its kinase activity and consequently prevents TNF-mediated RIPK1-dependent cell death (By similarity). Phosphorylates AMBRA1 following mitophagy induction, promoting AMBRA1 interaction with ATG8 family proteins and its mitophagic activity (PubMed:30217973)","source":"project UniProt records20261017/18"},{"partner":"TRIM27","hgnc":"HGNC:9975","core":true,"core_annotation":{"hgnc":"HGNC:9975","symbol_at_source":"TRIM27","accession":"P14373","function":"Histone modification erase cofactor","target":"#","pmids":["19351825"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":414,"hub_weight":0.32826608214930636,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Early endosome; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates ubiquitination of various substrates and thereby plays a role in diffent processes including proliferation, innate immunity, apoptosis, immune response or autophagy (PubMed:22829933, PubMed:24144979, PubMed:29688809, PubMed:36111389). Ubiquitinates PIK3C2B and inhibits its activity by mediating the formation of 'Lys-48'-linked polyubiquitin chains; the function inhibits CD4 T-cell activation. Acts as a regulator of retrograde transport: together with MAGEL2, mediates the formation of 'Lys-63'-linked polyubiquitin chains at 'Lys-220' of WASHC1, leading to promote endosomal F-actin assembly (PubMed:23452853). Has a transcriptional repressor activity by cooperating with EPC1. Induces apoptosis by activating Jun N-terminal kinase and p38 kinase and also increases caspase-3-like activity independently of mitochondrial events. May function in male germ cell development. Has DNA-binding activity and preferentially bound to double-stranded DNA. Forms a complex with and ubiquitinates the ubiquitin-specific protease USP7, which in turn deubiquitinates RIPK1 resulting in the positive regulation of TNF-induced apoptosis (PubMed:24144979). In addition, acts with USP7 or PTPN11 as an inhibitor of the antiviral signaling pathway by promoting kinase TBK1 ubiquitination and degradation (PubMed:26358190, PubMed:29688809). Acts as a negative regulator of NOD2 signaling by mediating ubiquitination of NOD2, promoting its degradation by the proteasome (PubMed:22829933). Alternatively, facilitates mitophagy via stabilization of active TBK1 (PubMed:36111389). Negatively regulates autophagy flux under basal conditions by directly polyubiquitinating ULK1 (PubMed:35670107). During starvation-induced autophagy, catalyzes non-degradative ubiquitination of the kinase STK38L promoting its activation and phosphorylation of ULK1 leading to its ubiquitination and degradation to restrain the amplitude and duration of autophagy (PubMed:35670107)\n(Microbial infection) Positively regulates hepatitis C virus replication by suppressing type I IFN response during infection","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"EVA1A","accession":"Q9H8M9","identity":0.503,"qcov":0.867,"tcov":0.895,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"MAMDC2":{"coreEvidence":[{"partner":"MECP2","hgnc":"HGNC:6990","core":true,"core_annotation":{"hgnc":"HGNC:6990","symbol_at_source":"MECP2","accession":"P51608","function":"Histone modification write cofactor, Histone modification write cofactor, TF","target":"DNA","pmids":["10773092"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1032,"hub_weight":0.2149667901961739,"quality":0.65,"programmes":["pubmed:38697112"],"pmids":["38697112"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromosomal protein that binds to methylated DNA. It can bind specifically to a single methyl-CpG pair. It is not influenced by sequences flanking the methyl-CpGs. Mediates transcriptional repression through interaction with histone deacetylase and the corepressor SIN3A. Binds both 5-methylcytosine (5mC) and 5-hydroxymethylcytosine (5hmC)-containing DNA, with a preference for 5-methylcytosine (5mC)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TBC1D28":{"coreEvidence":[{"partner":"H3-4","hgnc":"HGNC:4778","core":true,"core_annotation":{"hgnc":"HGNC:4778","symbol_at_source":"HIST3H3","accession":"Q16695","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":345,"hub_weight":0.35578403348241006,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KRABD5":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:35563538"],"pmids":["35563538"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"TRIM28","hgnc":"HGNC:16384","core":true,"core_annotation":{"hgnc":"HGNC:16384","symbol_at_source":"TRIM28","accession":"Q13263","function":"Histone modification read","target":"histone","pmids":["22464331"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1241,"hub_weight":0.19679854401103797,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 SUMO and ubiquitin ligase that plays a pivotal role in embryonic development, genomic imprinting, and maintenance of genomic stability through repression of repetitive and retroviral elements. Also involved in DNA repair, regulation of innate immunity or cellular energy homeostasis. Acts as a scaffold for assembling transcriptional repression complexes containing methyltransferases, histone deacetylases, and chromatin remodelers. Serves as a nuclear corepressor for KRAB domain-containing zinc finger proteins (KRAB-ZFPs), mediating gene silencing by recruiting CHD3, a subunit of the nucleosome remodeling and deacetylation (NuRD) complex, and SETDB1, which methylates histone H3 at 'Lys-9' (H3K9me), leading to heterochromatin formation. In collaboration with SETDB1, is also required for H3K9me3 and silencing of endogenous and introduced retroviruses in a DNA-methylation independent-pathway (By similarity). Functions as a coactivator for CEBPB and NR3C1 (glucocorticoid receptor) in transcriptional activation of ORM1, and as a corepressor for ERBB4. Inhibits E2F1 activity by promoting E2F1-HDAC1 complex formation and preventing E2F1 acetylation. This contributes to CDKN1A/p21(CIP1) regulation and provides a partial backup to suppress E2F1-mediated apoptosis in the absence of RB1. Mediates the nuclear localization of several KRAB-ZFP transcription factors including KOX1, ZNF268, and ZNF300 among others. In association with isoform 2 of ZFP90, is required for the transcriptional repressor activity of FOXP3 and the suppressive function of regulatory T-cells (Treg) (PubMed:23543754). Required to maintain a transcriptionally repressive state of genes in undifferentiated embryonic stem cells (ESCs) (PubMed:24623306). Acts as a corepressor for ZFP568. Beyond its nuclear functions, acts as a positive regulator of type I interferon (IFN-I) signaling by promoting Lys-63-linked ubiquitination of TBK1, facilitating TBK1-IRF3 complex formation (PubMed:38495890). Mediates TRAF6 SUMOylation to regulate its nucleo-cytoplasmic shuttling and modulate activation of the canonical NF-kappa-B signaling pathway (PubMed:39920527). Facilitates SUMOylation of NLRP3, protecting it from 'Lys-48'-linked ubiquitination and proteasomal degradation and thereby enhancing inflammasome activation (PubMed:34373456)\n(Microbial infection) Plays a critical role in the shutdown of lytic gene expression during the early stage of herpes virus 8 primary infection. This inhibition is mediated through interaction with herpes virus 8 protein LANA1\n(Microbial infection) Plays a positive role in SARS-CoV-2 virulence by mediating SUMOylation of nucleoprotein that promotes its RNA association leading to viral replication and innate antiviral immunity inhibition","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FAM186B":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"RUSF1":{"coreEvidence":[{"partner":"KAT6A","hgnc":"HGNC:13013","core":true,"core_annotation":{"hgnc":"HGNC:13013","symbol_at_source":"KAT6A","accession":"Q92794","function":"Histone modification write","target":"histone","pmids":["11313971"],"complexes":"MOZ/MORF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":415,"hub_weight":0.32791291789197646,"quality":0.65,"programmes":["pubmed:36537216"],"pmids":["36537216"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Nucleus, nucleoplasm; Nucleus, PML body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone acetyltransferase that acetylates lysine residues in histone H3 and histone H4 (in vitro) (PubMed:11742995, PubMed:11965546). Component of the MOZ/MORF complex which has a histone H3 acetyltransferase activity (PubMed:11965546). May act as a transcriptional coactivator for RUNX1 and RUNX2 (PubMed:12771199). Acetylates p53/TP53 at 'Lys-120' and 'Lys-382' and controls its transcriptional activity via association with PML (PubMed:23431171). May play a role in leukemogenic gene transcription (PubMed:39794553)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PRRT3":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:37788672"],"pmids":["37788672"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"RBBP4","hgnc":"HGNC:9887","core":true,"core_annotation":{"hgnc":"HGNC:9887","symbol_at_source":"RBBP4","accession":"Q09028","function":"Histone chaperone","target":"histone","pmids":["8858152"],"complexes":"NuRF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, NuRD, mSin3A, core HDAC, mSin3A-like complex, PRC2, CAF-1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":718,"hub_weight":0.2551551815399144,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome, telomere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core histone-binding subunit that may target chromatin assembly factors, chromatin remodeling factors and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA (PubMed:10866654). Component of the chromatin assembly factor 1 (CAF-1) complex, which is required for chromatin assembly following DNA replication and DNA repair (PubMed:8858152). Component of the core histone deacetylase (HDAC) complex, which promotes histone deacetylation and consequent transcriptional repression (PubMed:9150135). Component of the nucleosome remodeling and histone deacetylase complex (the NuRD complex), which promotes transcriptional repression by histone deacetylation and nucleosome remodeling (PubMed:16428440, PubMed:28977666, PubMed:39460621). Component of the PRC2 complex, which promotes repression of homeotic genes during development (PubMed:29499137, PubMed:31959557). Component of the NURF (nucleosome remodeling factor) complex (PubMed:14609955, PubMed:15310751)","source":"project UniProt records20261017/18"},{"partner":"RBBP7","hgnc":"HGNC:9890","core":true,"core_annotation":{"hgnc":"HGNC:9890","symbol_at_source":"RBBP7","accession":"Q16576","function":"Histone chaperone","target":"histone","pmids":["18571423"],"complexes":"NuRF, NuRD, mSin3A, core HDAC, mSin3A-like complex, PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":637,"hub_weight":0.2697780639425129,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core histone-binding subunit that may target chromatin remodeling factors, histone acetyltransferases and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA. Component of several complexes which regulate chromatin metabolism. These include the type B histone acetyltransferase (HAT) complex, which is required for chromatin assembly following DNA replication; the core histone deacetylase (HDAC) complex, which promotes histone deacetylation and consequent transcriptional repression; the nucleosome remodeling and histone deacetylase complex (the NuRD complex), which promotes transcriptional repression by histone deacetylation and nucleosome remodeling; and the PRC2/EED-EZH2 complex, which promotes repression of homeotic genes during development; and the NURF (nucleosome remodeling factor) complex","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ACOXL":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"CUL1","hgnc":"HGNC:2551","core":true,"core_annotation":{"hgnc":"HGNC:2551","symbol_at_source":"CUL1","accession":"Q13616","function":"Chromatin remodeling cofactor","target":"histone","pmids":["9663463"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":690,"hub_weight":0.25993762245501817,"quality":0.65,"programmes":["pubmed:21145461"],"pmids":["21145461"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Core component of multiple cullin-RING-based SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complexes, which mediate the ubiquitination of proteins involved in cell cycle progression, signal transduction and transcription. SCF complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:22017875, PubMed:22017877, PubMed:27565346). In the SCF complex, serves as a rigid scaffold that organizes the SKP1-F-box protein and RBX1 subunits. May contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme (PubMed:38326650). The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and exchange of the substrate recognition component is mediated by TIP120A/CAND1 (PubMed:12609982, PubMed:38326650). The functional specificity of the SCF complex depends on the F-box protein as substrate recognition component (PubMed:38326650). SCF(BTRC) and SCF(FBXW11) direct ubiquitination of CTNNB1 and participate in Wnt signaling. SCF(FBXW11) directs ubiquitination of phosphorylated NFKBIA. SCF(BTRC) directs ubiquitination of NFKBIB, NFKBIE, ATF4, SMAD3, SMAD4, CDC25A, FBXO5 and probably NFKB2. SCF(BTRC) and/or SCF(FBXW11) direct ubiquitination of CEP68 (PubMed:25503564, PubMed:25704143). SCF(SKP2) directs ubiquitination of phosphorylated CDKN1B/p27kip and is involved in regulation of G1/S transition. SCF(SKP2) directs ubiquitination of ORC1, CDT1, RBL2, ELF4, CDKN1A, RAG2, FOXO1A, and probably MYC and TAL1. SCF(FBXW7) directs ubiquitination of CCNE1, NOTCH1 released notch intracellular domain (NICD), and probably PSEN1. SCF(FBXW2) directs ubiquitination of GCM1. SCF(FBXO32) directs ubiquitination of MYOD1. SCF(FBXO7) directs ubiquitination of BIRC2 and DLGAP5. SCF(FBXO33) directs ubiquitination of YBX1. SCF(FBXO1) directs ubiquitination of BCL6 and DTL but does not seem to direct ubiquitination of TP53. SCF(BTRC) mediates the ubiquitination of NFKBIA at 'Lys-21' and 'Lys-22'; the degradation frees the associated NFKB1-RELA dimer to translocate into the nucleus and to activate transcription. SCF(CCNF) directs ubiquitination of CCP110. SCF(FBXL3) and SCF(FBXL21) direct ubiquitination of CRY1 and CRY2. SCF(FBXO9) directs ubiquitination of TTI1 and TELO2. SCF(FBXO10) directs ubiquitination of BCL2. Neddylated CUL1-RBX1 ubiquitinates p53/TP53 recruited by Cul7-RING(FBXW8) complex (PubMed:35982156). SCF(BTRC) directs 'Lys-48'-linked ubiquitination of UBR2 in the T-cell receptor signaling pathway (PubMed:38225265). The SCF(FBXO31) protein ligase complex specifically mediates the ubiquitination of proteins amidated at their C-terminus in response to oxidative stress (PubMed:39880951)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PDZD9":{"coreEvidence":[{"partner":"PBK","hgnc":"HGNC:18282","core":true,"core_annotation":{"hgnc":"HGNC:18282","symbol_at_source":"PBK","accession":"Q96KB5","function":"Histone modification write","target":"histone","pmids":["16982762"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":193,"hub_weight":0.45360921162651446,"quality":0.65,"programmes":["pubmed:36115835"],"pmids":["36115835"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Phosphorylates MAP kinase p38. Seems to be active only in mitosis. May also play a role in the activation of lymphoid cells. When phosphorylated, forms a complex with TP53, leading to TP53 destabilization and attenuation of G2/M checkpoint during doxorubicin-induced DNA damage","source":"project UniProt records20261017/18"}],"near_known_relatives":[]}};
